mapper.select:
SELECT g.id, g.name, g.description, g.image, g.creator, user.name AS creator_name, user.avatar AS creator_avatar, IFNULL(fav_counts.favorite_count, 0) AS favorite_count, IFNULL(collect_counts.collect_count, 0) AS collect_count, EXISTS ( SELECT 1 FROM tb_gift_favorite WHERE gift_id = g.id AND user_id = #{creatorId} ) AS is_favorited_by_user, EXISTS ( SELECT 1 FROM tb_gift_collect WHERE gift_id = g.id AND user_id = #{creatorId} ) AS is_collected_by_user FROM tb_gift g JOIN tb_user user ON g.creator = user.id LEFT JOIN ( SELECT gift_id, COUNT(*) AS favorite_count FROM tb_gift_favorite GROUP BY gift_id ) fav_counts ON g.id = fav_counts.gift_id LEFT JOIN ( SELECT gift_id, COUNT(*) AS collect_count FROM tb_gift_collect GROUP BY gift_id ) collect_counts ON g.id = collect_counts.gift_id
creator = #{creatorId}
ORDER BY favorite_count DESC limit #{start},#{pageSize}
